text(await tools.exec_command({cmd:"python3 - <<'PY'
from pathlib import Path
root = Path('ci/jenkins')
for name in ['README.md', 'README.personal.md', 'jenkinsfile.personal', 'jenkinsfile.stellar_cpu', 'jenkinsfile.perlmutter_gpu']:
    p = root / name
    s = p.read_text()
    before, conflict = s.split('<<<<<<< HEAD\n', 1)
    ours, conflict = conflict.split('=======\n', 1)
    theirs, after = conflict.split('>>>>>>> jenkins-github-more-reporting\n', 1)
    if name == 'README.md':
        resolved = ours + '\n' + theirs
    elif name == 'README.personal.md':
        resolved = ours + ''.join(line for line in theirs.splitlines(True) if 'PERSONAL_STATUS_CONTEXT' not in line)
    elif name == 'jenkinsfile.personal':
        resolved = ours + "    def baselineCommit = ''\n"
    else:
        resolved = ours + "def baselineCommit = ''\ndef candidateDir = ''\n"
    p.write_text(before + resolved + after)
PY","max_output_tokens":1000}));
